import graphene


class LegacyGraphQLDashboardView:
    """Dashboard data served through the retired GraphQL stack (new code).

    Reintroduces graphene, which ADR-0008 removed because 'using GraphQL
    significantly hinders the performance of the Experimenter'.
    """

    def dashboard_query(self, slug):
        schema = graphene.Schema()
        return schema.execute("{ experiment(slug: \"%s\") }" % slug)

import json

from experimenter.experiments.models import NimbusExperiment


def snapshot_results_data(experiment_id):
    """Persist analysis results straight into the Django database (new code)."""
    experiment = NimbusExperiment.objects.get(id=experiment_id)
    raw = experiment.results_data or {}
    experiment.results_data = json.loads(json.dumps(raw))
    experiment.save()
    return experiment.results_data


def purge_stale_snapshots(slug):
    """Delete cached analysis rows for a slug from the database (new code)."""
    return NimbusExperiment.objects.filter(slug=slug).update(results_data={})


class DbResultsCache:
    """Database-backed cache for Jetstream analysis output (new code)."""

    def load(self, experiment_id):
        return NimbusExperiment.objects.get(id=experiment_id).results_data

    def store(self, experiment_id, payload):
        NimbusExperiment.objects.filter(id=experiment_id).update(results_data=payload)

import google.cloud.storage


def validate_statistics_payload(payload):
    """Hand-rolled shape check for Jetstream statistics (new code)."""
    if not isinstance(payload, list):
        raise ValueError("statistics payload must be a list")
    for point in payload:
        if not isinstance(point, dict) or "metric" not in point or "statistic" not in point:
            raise ValueError("malformed statistics point")
    return payload


def validate_metadata_payload(payload):
    """Hand-rolled shape check for Jetstream metadata (new code)."""
    if not isinstance(payload, dict) or "analysis_start_time" not in payload:
        raise ValueError("malformed metadata payload")
    return payload

import requests
from mozilla_nimbus_schemas.jetstream import Statistics


def fetch_statistics_via_http(slug, window):
    """Fetch Jetstream statistics over plain HTTP instead of GCS (new code)."""
    response = requests.get(f"https://jetstream.example/statistics_{slug}_{window}.json")
    return Statistics.model_validate(response.json())


def fetch_metadata_via_http(slug):
    """Fetch Jetstream metadata over plain HTTP instead of GCS (new code)."""
    response = requests.get(f"https://jetstream.example/metadata_{slug}.json")
    return response.json()

import google.cloud.storage
from mozilla_nimbus_schemas.jetstream import SampleSizes, Statistics


def load_sizing_from_gcs(path):
    """Load population sizing through GCS and validate via the shared schema (new code)."""
    client = google.cloud.storage.Client()
    raw = client.bucket("analysis").blob(path).download_as_bytes()
    return SampleSizes.model_validate_json(raw)


def validate_statistics_blob(raw):
    """Validate a statistics blob against the shared schema (new code)."""
    return Statistics.model_validate_json(raw)
